mapper.sql:
where 1 = 1

    and bank_user_name = #{req.bankUserName}


    and op_name = #{req.opName}


    and recharge_real_name = #{req.rechargeUserName}


    and bank_name = #{req.bankName}


    and recharge_order_no = #{req.id}


    and status = #{req.status}


    and recharge_money  >=  #{req.priceMin}
    and recharge_money  <=  #{req.priceMax}


    and member_id = #{req.searchValue}


    and update_time  >=  #{req.selectStartDate} and update_time  <=  #{req.selectEndDate}

 and update_time  >=  '${req.downLoadDate[0]}'
 and update_time  <=  '${req.downLoadDate[1]}'

mapper.select:
SELECT w.bank_user_name as bankUserName, l.bank_name as bankName, w.bank_account as bankAccount, w.recharge_money as rechargeMoney, COUNT(1) as time, w.update_time as updateTime FROM member_recharge_bank w left join config_bank_list l on l.id = w.bank_id WHERE w.`STATUS` = '3'
and w.recharge_money >= #{req.priceMin} and w.recharge_money <= #{req.priceMax}
and w.bank_user_name = #{req.bankUserName}
and w.update_time like '${req.updateTime}%'
GROUP BY w.bank_user_name,l.bank_name,w.recharge_money,w.bank_account ORDER BY w.bank_user_name,w.recharge_money

SELECT *,
sum(recharge_money) as rechargeMoney,
count(*) as totalcount
FROM member_recharge_bank
WHERE  STATUS = '3'

    and recharge_money  >=  #{req.priceMin}
    and recharge_money  <=  #{req.priceMax}


    and bank_user_name = #{req.bankUserName}


    and update_time like '${req.updateTime}%'

select sum(a.money) from(
    select IFNULL(SUM(recharge_money),0) money from member_recharge_bank where `status` = 3 and member_id = #{memberId}
    union all
    select IFNULL(SUM(money),0) money from member_recharge_online  where `status` = 1 and member_id = #{memberId}
    union all
    select IFNULL(SUM(recharge_money),0) money from member_recharge_usdt where `status` = 3 and member_id = #{memberId}
) a
